 if(ret==='sydney')days=days.map(d=>d.date===last?{...d,region:'시드니',hotel:'sydlast',title:'국제선 전날, 다시 시드니로',detail:'골드코스트 → 시드니 국내선 · 마지막 밤',places:['domestic'],tag:'별도 발권 · 전날 이동'}:d.date===end?{...d,title:'시드니에서 인천으로',detail:'대한항공·아시아나 귀국편 비교 중',places:[],tag:'항공편·시간 미정'}:d);
