function themeIcon(){const dark=document.documentElement.dataset.theme==='dark';return '<svg viewBox="0 0 24 24" width="22" height="22" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true">'+(dark?'<circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1 1m12 12 1 1M5 19l1-1M18 6l1-1"/>':'<path d="M20 14A8 8 0 0 1 10 4a8.5 8.5 0 1 0 10 10Z"/>')+'</svg>'}
function go(to){if(to==='today'){itineraryMode='detail';const m=derive(selection,records),tz=m.day.region==='골드코스트'||m.day.region==='브리즈번'?'Australia/Brisbane':'Australia/Sydney',now=todayIn(tz);city='all';if(m.days.some(d=>d.date===now))selection.day=now;else toast('여행 기간 밖입니다. 선택한 날짜의 일정을 표시합니다.');to='itinerary'}view=validViews.includes(to)?to:'cover';history.replaceState(null,'','#'+view);render();window.scrollTo({top:0,behavior:'instant'})}
function field(name,label,value,type='text',options=[]){return `<label>${label}${type==='select'?`<select name="${name}">${options.map(o=>`<option ${value===o?'selected':''}>${esc(o)}</option>`).join('')}</select>`:type==='textarea'?`<textarea name="${name}">${esc(value)}</textarea>`:`<input name="${name}" type="${type}" value="${esc(value)}" ${type==='number'?'min="0" step="0.01"':''}>`}</label>`}
