function editCost(key){const m=derive(selection,records),r=m.rows.find(x=>x.key===key);if(!r)return;const recordKey=key.startsWith('hotel.')?'cost.'+key+'.'+m.plan+'.'+m.end:'cost.'+key+'.'+m.plan+'.'+m.ret+'.'+m.end;openEditor(r.label+' · 예상비용 입력',field('low','최소 금액',r.known?r.low:'','number')+field('high','최대 금액',r.known?r.high:'','number')+field('currency','통화',r.currency,'select',['KRW','AUD'])+'<p class="fine">현재 여행안·귀국일의 견적에 적용합니다. JW를 원화로 입력한다면 현금 환산 기준을 메모로 남기세요. 포인트는 현금이 아닙니다.</p>',fd=>{const low=Number(fd.get('low')),high=Number(fd.get('high'));if(fd.get('low')===''||fd.get('high')===''||!Number.isFinite(low)||!Number.isFinite(high)||low<0||high<low)throw Error('최대 금액은 최소 금액 이상이어야 합니다.');changeRecord({[recordKey]:{low,high,currency:fd.get('currency')}})})}
