document.addEventListener('click',e=>{const el=e.target.closest('button,a');if(!el)return;if(el.hasAttribute('data-open-sheet')){$('#plan-sheet').showModal();return}if(el.hasAttribute('data-open-manage')){updateSync();$('#management').showModal();return}if(el.dataset.plan){setSelection({plan:Number(el.dataset.plan)});return}if(el.dataset.ret){setSelection({ret:el.dataset.ret});return}if(el.dataset.view){e.preventDefault();if(el.dataset.bookingTab)bookingTab=el.dataset.bookingTab;go(el.dataset.view);return}if(el.dataset.goto){go(el.dataset.goto);return}if(el.dataset.mode){itineraryMode=el.dataset.mode;render();window.scrollTo({top:0,behavior:'instant'});return}if(el.dataset.openDay){itineraryMode='detail';city='all';selection.day=el.dataset.openDay;go('itinerary');return}if(el.dataset.filterCity){city=el.dataset.filterCity;render();return}if(el.dataset.day){setSelection({day:el.dataset.day});return}if(el.dataset.bookingTab){bookingTab=el.dataset.bookingTab;render();return}if(el.dataset.editHotel){editBooking('hotel',el.dataset.editHotel);return}if(el.dataset.editFlight){editBooking('flight',el.dataset.editFlight);return}if(el.dataset.editCost){editCost(el.dataset.editCost);return}if(el.hasAttribute('data-map-expand')){const card=el.closest('.map-card'),on=card.classList.toggle('expanded');el.setAttribute('aria-pressed',String(on));el.textContent=on?'지도 작게 보기':'지도 크게 보기';liveMap?.invalidateSize();return}if(el.hasAttribute('data-close')){el.closest('dialog').close();return}if(el.dataset.focusTask){const target=$('[data-task="'+el.dataset.focusTask+'"]');target?.focus();target?.scrollIntoView({block:'center'});return}if(el.dataset.editDay){editExtraDay(el.dataset.editDay);return}if(el.hasAttribute('data-edit-emergency')){editEmergency();return}if(el.id==='save-day-note'){changeRecord({['day.'+el.dataset.date+'.note']:$('#day-note').value.slice(0,5000)});toast('날짜 메모를 저장했습니다.')}if(el.id==='save-general'){changeRecord({'general.note':$('#general-note').value.slice(0,10000)});toast('여행 메모를 저장했습니다.')}});
document.addEventListener('change',e=>{if(e.target.dataset.task){changeRecord({['done.'+e.target.dataset.task]:e.target.checked});toast(e.target.checked?'준비 하나를 마쳤습니다.':'미완료로 바꿨습니다.')}if(e.target.name==='ret-city')setSelection({ret:e.target.value});if(e.target.dataset.owner)changeRecord({['general.owner.'+e.target.dataset.owner]:e.target.value});if(e.target.id==='owner-filter'){ownerFilter=e.target.value;render()}});
$('#early').addEventListener('change',e=>setSelection({early:e.target.checked}));
$('#theme').onclick=()=>{const dark=document.documentElement.dataset.theme!=='dark';document.documentElement.dataset.theme=dark?'dark':'light';changeRecord({'settings.theme':dark?'dark':'light'})};
$('#export').onclick=exportData;$('#import').onclick=()=>$('#import-file').click();$('#download').onclick=downloadHTML;$('#print').onclick=printGuide;$('#sync-now').hidden=!CLOUD_ENABLED;$('#sync-now').onclick=()=>syncCloud();
$('#fx-input').onchange=e=>{const n=Number(e.target.value);if(n>=1&&n<=10000){changeRecord({'settings.fx':n});toast('환율 가정을 변경했습니다.')}else toast('1~10,000원 범위로 입력해 주세요.')};
$('#editor-form').onsubmit=e=>{e.preventDefault();try{editorSave?.(new FormData(e.target));$('#editor').close();toast('입력 내용을 저장했습니다.')}catch(err){toast(err.message)}};
$('#import-file').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>2000000)throw Error('백업 파일은 2MB 이하여야 합니다.');const obj=JSON.parse(await file.text());if(obj.format!=='australia-atlas'||obj.version!==1||!obj.records||Array.isArray(obj.records))throw Error('이 여행 현황판의 백업 파일이 아닙니다.');const clean={};for(const[k,v]of Object.entries(obj.records)){if(validRecord(k,v))clean[k]=v}if(obj.selection)selection={...selection,plan:obj.selection.plan===2?2:1,ret:obj.selection.ret==='sydney'?'sydney':'brisbane',early:obj.selection.early===true,day:/^2027-\d\d-\d\d$/.test(obj.selection.day)?obj.selection.day:selection.day};changeRecord(clean);$('#management').close();toast('백업을 병합했습니다. 같은 항목은 가져온 값으로 갱신했습니다.')}catch(err){toast(err.message)}e.target.value=''};
addEventListener('hashchange',()=>{view=validViews.includes(location.hash.slice(1))?location.hash.slice(1):'cover';render()});addEventListener('online',()=>syncCloud());document.addEventListener('visibilitychange',()=>{if(!document.hidden)syncCloud()});
for(const [id,key]of [['mile-oz','oz'],['mile-ke','ke']])$('#'+id).onchange=e=>{const v=e.target.value;if(v!==''&&(!Number.isFinite(Number(v))||Number(v)<0||Number(v)>1000)){toast('0~1,000원 범위로 입력하세요.');return}changeRecord({['general.mile.'+key]:v})};
render();syncCloud();
